def decode_packets(records):
    fragments = {}
    for record in records:
        parts = record.split("|", 1)
        if len(parts) != 2 or not parts[0].isdecimal():
            continue
        fragments[int(parts[0])] = parts[1]
    return "".join(fragments[i] for i in sorted(fragments))

