def merge_observations(reports):
    result = {}
    for report in reports:
        target = report["target"]
        if target not in result:
            result[target] = {"latest": None, "sources": set()}
        result[target]["latest"] = report["value"]
        result[target]["sources"].add(report["source"])
    return {key: {"latest": value["latest"], "sources": sorted(value["sources"])}
            for key, value in result.items()}

