    if clip is not None and clip[0] > clip[1]:
        raise ValueError("Неверный диапазон")
    result = [(x + offset) * scale for x in values]
    if clip is not None:
        lo, hi = clip
        result = [min(hi, max(lo, x)) for x in result]
    return result

