exercises.solution:
def choose_threshold(scores, labels, min_recall):
    if not 0 <= min_recall <= 1:
        raise ValueError("min_recall вне диапазона")
    total = sum(labels)
    best = 0.0
    for threshold in sorted(set(scores + [0.0, 1.0])):
        tp = sum(label == 1 and score >= threshold for score, label in zip(scores, labels))
        recall = tp / total if total else 1.0
        if recall >= min_recall:
            best = threshold
    return best

