exercises.solution:
class EnergyLedger:
    def __init__(self, total):
        if total < 0:
            raise ValueError("Отрицательная энергия")
        self.total = total
        self.spent = 0
        self.reserved = {}
        self.committed = set()
    def available(self):
        return self.total - self.spent - sum(self.reserved.values())
    def reserve(self, key, cost):
        if cost < 0 or key in self.committed:
            return False
        if key in self.reserved:
            return self.reserved[key] == cost
        if cost > self.available():
            return False
        self.reserved[key] = cost
        return True
    def commit(self, key):
        if key in self.committed:
            return True
        if key not in self.reserved:
            return False
        self.spent += self.reserved.pop(key)
        self.committed.add(key)
        return True
    def cancel(self, key):
        if key not in self.reserved:
            return False
        del self.reserved[key]
        return True

