exercises.solution:
def low_rank_update(W, A, B):
    n = len(W)
    if n == 0:
        if A or B:
            raise ValueError("Несовместимые пустые матрицы")
        return []
    m = len(W[0])
    if any(len(row) != m for row in W) or len(A) != n:
        raise ValueError("Неверная форма")
    r = len(A[0])
    if any(len(row) != r for row in A) or len(B) != r or any(len(row) != m for row in B):
        raise ValueError("Несовместимые формы")
    return [[W[i][j] + sum(A[i][k] * B[k][j] for k in range(r))
             for j in range(m)] for i in range(n)]

