exercises.solution:
def calibration_bins(probs, labels, bins):
    if bins <= 0 or any(not 0 <= p <= 1 for p in probs):
        raise ValueError("Неверные вероятности или число интервалов")
    counts, sums, positives = [0]*bins, [0.0]*bins, [0]*bins
    for p, label in zip(probs, labels):
        index = min(bins-1, int(p*bins))
        counts[index] += 1
        sums[index] += p
        positives[index] += label
    return [{"count": counts[i], "mean_prob": sums[i]/counts[i] if counts[i] else None,
             "positive_rate": positives[i]/counts[i] if counts[i] else None}
            for i in range(bins)]

