import heapq
def dependency_order(graph):
    nodes = set(graph)
    for deps in graph.values():
        nodes.update(deps)
    dependents = {node: [] for node in nodes}
    remaining = {node: len(set(graph.get(node, []))) for node in nodes}
    for node, deps in graph.items():
        for dep in set(deps):
            dependents[dep].append(node)
    ready = [node for node in nodes if remaining[node] == 0]
    heapq.heapify(ready)
    result = []
    while ready:
        node = heapq.heappop(ready)
        result.append(node)
        for following in dependents[node]:
            remaining[following] -= 1
            if remaining[following] == 0:
                heapq.heappush(ready, following)
    if len(result) != len(nodes):
        raise ValueError("Цикл зависимостей")
    return result

