def rescue_value(capacity, items):
    if capacity < 0 or any(cost <= 0 for cost, value in items):
        raise ValueError("Неверная вместимость или цена")
    best = [0] * (capacity + 1)
    for cost, value in items:
        for remaining in range(capacity, cost-1, -1):
            best[remaining] = max(best[remaining], best[remaining-cost] + value)
    return best[capacity]

